/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import org.slf4j.Logger;import org.slf4j.LoggerFactory;public class Bean<T> implements Cloneable {	private static Logger log = LoggerFactory.getLogger(Bean.class);	public T copy() {		try {			Object object = this.clone();			@SuppressWarnings("unchecked")			T bean = (T) object;			return bean;		} catch (Exception ex) {			log.error("copy: " + ex.toString());		}		return null;	}	@Override	protected Object clone() throws CloneNotSupportedException {		try {			return super.clone();		} catch (Exception ex) {			log.error("clone: " + ex.toString());		}		return null;	}	protected T bean() {		@SuppressWarnings("unchecked")		T bean = (T) this;		return bean;	}}